// Generate reference from the actual package export map and compiler export symbols.
// No copied API declarations. --check rejects any stale/missing generated bytes.
import assert from "node:assert/strict"
import { execFileSync } from "node:child_process"
import { createHash } from "node:crypto"
import { mkdirSync, readFileSync, readdirSync, writeFileSync } from "node:fs"
import { resolve, join } from "node:path"
import { API, SymbolFlags } from "typescript/unstable/sync"
import { publicModules } from "../../../../scripts/SourceExports.mjs"

const { openDeclarations } = (await import(
  new URL("./Declarations.ts", import.meta.url).href
)) as typeof import("./Declarations.js")

const root = resolve(import.meta.dirname, "../../../..")
const output = join(root, "apps/website/src/content/docs/reference")
const moduleOutput = join(output, "modules")
const check = process.argv.includes("--check")
const manifest = JSON.parse(readFileSync(join(root, "package.json"), "utf8"))
const groups = {
  definitions: {
    title: "Definitions and production",
    intro:
      "Declare logical queues and versioned payloads, then identify each business consequence. Constructors do not create storage or start workers. The root entrypoint intentionally exports nothing; use the focused subpaths below.",
    modules: [
      "index",
      "Job",
      "JobQueue",
      "JobProducer",
      "JobGroup",
      "JobApi",
      "JobIdentity",
      "JobId",
      "JobContract",
      "JobEnqueue",
      "JobTransaction"
    ]
  },
  payloads: {
    title: "Payloads and policy",
    intro:
      "Schema owns the encoded/domain boundary. Protected markers and encrypted transformations do not supply cryptographic keys or algorithms. Persisted policy is first-write-wins; a matching duplicate does not refresh its retention or retry budget.",
    modules: [
      "JobPayload",
      "JobPayloadCodec",
      "JobPolicy",
      "JobRetryPolicy",
      "JobFailure",
      "FailureCode"
    ]
  },
  workers: {
    title: "Handlers and workers",
    intro:
      "Install every catalog group before constructing a worker. A finite drain and a scoped polling Layer are separate operations. Local permits bound claims for one worker; they do not provide global concurrency or exactly-once external delivery.",
    modules: ["JobStorage", "JobWorker", "JobPolling", "JobSchedule"]
  },
  lifecycle: {
    title: "Lifecycle and operator ports",
    intro:
      "These are storage and application integration contracts. Handlers receive payload and metadata, never lease tokens or finalization authority. Database time and exact ownership fencing remain storage responsibilities. OutcomeUnknown is an attempt outcome, not a durable state.",
    modules: ["JobLifecycle", "JobStore", "JobOperators"]
  },
  postgresql: {
    title: "PostgreSQL integration",
    intro:
      "The application owns migrations, one configured native client, finite control timeouts and pool lifetime. Use the same PgClient for domain writes and enqueue. Runtime imports do no SQL. Drizzle declarations are optional and do not themselves qualify a transaction adapter.",
    modules: [
      "PostgreSqlJobs",
      "PostgreSqlTransaction",
      "PostgreSqlNative",
      "PostgreSqlSchema",
      "PostgreSqlDrizzleSchema"
    ]
  },
  "durable-object-sqlite": {
    title: "Durable Object SQLite integration",
    intro:
      "Use a single SQLite-backed Durable Object for domain writes and enqueue. The application owns object routing, migrations, commit acknowledgement and bounded drain scheduling.",
    modules: ["DurableObjectSqlite"]
  }
}
const modules = publicModules(manifest)
const exportedModules = modules.map((module) => module.name)
const assigned = Object.values(groups).flatMap((group) => group.modules)
assert.deepEqual(
  [...assigned].sort(),
  [...exportedModules].sort(),
  "Every public subpath needs exactly one reference group"
)
assert.equal(new Set(assigned).size, assigned.length)
const api = new API({ cwd: root })
process.on("exit", () => api.close())
const snapshot = api.updateSnapshot({ openProjects: [join(root, "tsconfig.build.json")] })
const project = snapshot.getProject(join(root, "tsconfig.build.json"))
assert(project, "Build project must be available to the pinned TypeScript compiler")
const { program, checker } = project
const declarations = openDeclarations(root)
process.on("exit", declarations.close)
const escaped = (value: string) =>
  value
    .replaceAll("|", "&#124;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll("{", "&#123;")
    .replaceAll("}", "&#125;")
    .replace(/\s+/g, " ")
    .trim()
const inventory: Array<{
  subpath: string
  filename: string
  sha256: string
  symbols: Array<{ name: string; kind: string; category: string; description: string }>
}> = []
const generated = new Map<string, string>()
const moduleSlug = (name: string) =>
  name.replace(/([a-z])([A-Z])/g, "$1-$2").toLowerCase()
assert.equal(
  new Set(exportedModules.map(moduleSlug)).size,
  exportedModules.length,
  "Duplicate module slugs"
)
let directory = `---\ntitle: Public modules\ndescription: Browse the public subpaths of effect-jobs.\n---\n\n{/* Generated by tests/docs-reference/Reference.ts. */}\n\nEach module lists its public exports and their TypeScript declarations. The bare \`effect-jobs\` entrypoint is intentionally empty. For complete usage, see the [checked examples](/docs/reference/examples).\n`
const navigation: Array<{
  title: string
  href: string
  modules: Array<{ title: string; href: string }>
}> = []
const savePage = (path: string, text: string) => {
  const formatted = execFileSync(
    join(root, "node_modules/.bin/oxfmt"),
    ["--config", join(root, ".oxfmtrc.json"), "--stdin-filepath", path],
    { input: text, encoding: "utf8", maxBuffer: 8 * 1024 * 1024 }
  )
  generated.set(path, formatted)
}
for (const [slug, group] of Object.entries(groups)) {
  const navGroup = {
    title: group.title,
    href: `/docs/reference/${slug}`,
    modules: [] as Array<{ title: string; href: string }>
  }
  navigation.push(navGroup)
  directory += `\n## ${group.title}\n\n`
  let body = `---\ntitle: ${group.title}\ndescription: Source-derived public API reference for ${group.title.toLowerCase()}.\n---\n\n{/* Generated by tests/docs-reference/Reference.ts. Edit public source JSDoc, then regenerate. */}\n\n${group.intro}\n\nOpen a module or symbol to see its TypeScript declaration. See [checked examples](/docs/reference/examples) for composition.\n`
  for (const name of group.modules) {
    const entry = modules.find((module) => module.name === name)!
    const filename = entry.source
    const file = program.getSourceFile(join(root, filename))
    assert(file, `Missing ${filename}`)
    const module = checker.getSymbolAtLocation(file)
    assert(module, `Not a module: ${filename}`)
    const exports = [...checker.getExportsOfModule(module)].sort((a, b) =>
      a.name.localeCompare(b.name, "en")
    )
    const symbols = exports.map((symbol) => {
      const target =
        symbol.flags & SymbolFlags.Alias ? checker.getAliasedSymbol(symbol) : symbol
      const descriptions = target.getDocumentationComment(checker).split(/\n\s*\n/)[0]
      const tags = target.getJsDocTags(checker)
      const category = tags.find((tag) => tag.name === "category")?.text
      // Merged Schema/type names are represented once; both namespaces stay explicit.
      const namespaces = [
        target.flags & SymbolFlags.Value ? "value" : null,
        target.flags & SymbolFlags.Type ? "type" : null
      ]
        .filter(Boolean)
        .join(" + ")
      return {
        name: symbol.name,
        kind: namespaces,
        category: category ?? "contract",
        description:
          descriptions || "Public integration contract; see the exported declaration."
      }
    })
    const subpath = name === "index" ? "effect-jobs" : `effect-jobs/${name}`
    const signatures = declarations.forModule(entry.types)
    assert.deepEqual(
      [...signatures.keys()].sort(),
      symbols.map((symbol) => symbol.name).sort(),
      `Declarations don't match the public exports of ${subpath}`
    )
    inventory.push({
      subpath,
      filename,
      sha256: createHash("sha256")
        .update(readFileSync(join(root, filename)))
        .digest("hex"),
      symbols
    })
    body += `\n## ${name === "index" ? "Root entrypoint" : name}\n\n`
    if (symbols.length === 0) {
      body += "This entrypoint is intentionally empty. Import a focused subpath.\n"
    } else {
      const slugForModule = moduleSlug(name)
      const url = `/docs/reference/modules/${slugForModule}`
      navGroup.modules.push({ title: name, href: url })
      directory += `- [\`${subpath}\`](${url})\n`
      body += `[\`${subpath}\` signatures](${url})\n\n`
      body += "| Export | Kind | Contract |\n| --- | --- | --- |\n"
      let page = `---\ntitle: ${name}\ndescription: Public TypeScript declarations for ${subpath}.\n---\n\n{/* Generated by tests/docs-reference/Reference.ts. */}\n\n[Public modules](/docs/reference/modules) / [${group.title}](${navGroup.href})\n\n**Import path:** \`${subpath}\` · [Source](https://github.com/nr1brolyfan/effect-jobs/blob/main/${filename}) · [Checked examples](/docs/reference/examples)\n\n`
      const anchors = new Map<string, number>()
      for (const symbol of symbols) {
        assert.match(symbol.name, /^[A-Za-z][A-Za-z0-9]*$/)
        // Match the heading slugs for exports that differ only by casing, e.g. Match/match.
        const base = symbol.name.toLowerCase()
        const index = anchors.get(base) ?? 0
        anchors.set(base, index + 1)
        body += `| [\`${symbol.name}\`](${url}#${index ? `${base}-${index}` : base}) | ${symbol.kind} | ${escaped(symbol.description)} |\n`
        const { declaredAs, signature, resolved } = signatures.get(symbol.name)!
        page += `## ${symbol.name}\n\n`
        if (
          symbol.description !==
          "Public integration contract; see the exported declaration."
        ) {
          page += `${escaped(symbol.description)}\n\n`
        }
        if (declaredAs !== symbol.name) {
          page += `Exported as \`${symbol.name}\`; declared as \`${declaredAs}\`.\n\n`
        }
        page += `\`\`\`ts title="Type declaration"\n${signature}\n\`\`\`\n\n`
        if (resolved) {
          page += `<details>\n<summary>Expand referenced declaration</summary>\n\n\`\`\`ts title="Referenced declaration"\n${resolved}\n\`\`\`\n\n</details>\n\n`
        }
      }
      savePage(join(moduleOutput, `${slugForModule}.mdx`), page)
    }
  }
  if (slug === "lifecycle") {
    body += `
### Allowed source states

Every command checks the exact job ID, expected state and lifecycle version
under lock. Supply the values from the snapshot the application authorized.

| Command | Allowed source | Effect after commit |
| --- | --- | --- |
| \`cancel\` | Pending or RetryScheduled | Stops future execution. An active handler keeps running, and earlier external effects cannot be undone. |
| \`retryNow\` | RetryScheduled, strictly in the future | Advances availability to database time. Keeps existing limits and counters. |
| \`redrive\` | Dead or eligible, investigated Isolated | Creates a Pending successor with lineage and a copy of the valid original payload. |
| \`correctedRedrive\` | Dead or eligible, investigated Isolated | Creates a Pending successor with lineage and a complete replacement payload. |

Both redrive methods use a definition whose public \`name\` and \`version\` match the
source. Use a new producer identity for the successor. A redrive leaves the
source as it was. Execution is a later worker operation.

### Transaction and receipt

The application checks authorization and command admission in the same-client
transaction as the operator call and receipt write. Admit only a fresh command
after checking its exact identity and any existing receipt. Keep the result
provisional inside the transaction and return it after the outer commit is
acknowledged. If commit is unknown, read the receipt for the original command
outside that transaction. A missing receipt leaves the outcome unresolved and
does not authorize replay.

For every redrive, require explicit application confirmation that this exact
command may repeat an external effect. This applies even when
\`correctedRedrive\` supplies a complete replacement payload. If confirmation is
missing or denied, fail the transaction before calling the operator or writing
the receipt.

<CodeExample sourcePath="ReportOperators.ts" region="transaction" role="Composition" />

<CodeExample sourcePath="ReportOperators.ts" region="actions" role="Checked scenario" />
`
    body = body.replace(
      "{/* Generated",
      'import CodeExample from "../../../components/docs/CodeExample.astro"\n\n{/* Generated'
    )
  }
  savePage(join(output, `${slug}.mdx`), body)
}
savePage(join(moduleOutput, "index.mdx"), directory)
generated.set(
  join(output, "module-navigation.json"),
  JSON.stringify(navigation, null, 2) + "\n"
)
generated.set(
  join(output, "public-exports.json"),
  JSON.stringify(inventory, null, 2) + "\n"
)
if (!check) {
  mkdirSync(moduleOutput, { recursive: true })
}
assert(
  readdirSync(moduleOutput).every((file) => generated.has(join(moduleOutput, file))),
  "Stale module pages: remove obsolete generated files"
)
for (const [path, bytes] of generated) {
  if (check) {
    assert.equal(readFileSync(path, "utf8"), bytes, `Stale reference: ${path}`)
  } else {
    writeFileSync(path, bytes)
  }
}
console.log(
  `${inventory.length} public entrypoints, ${inventory.reduce((n, item) => n + item.symbols.length, 0)} exported names: reference ${check ? "consistent" : "generated"}`
)

snapshot.dispose()
api.close()
process.removeListener("exit", declarations.close)
declarations.close()
